# Give the selected people a grade together from a from-date (blank: the sheet's today), in list order. Each is
# graded exactly as the person form's edit would (name and terms kept), with its PERSON_EDITED line and then how the
# sheet's figures moved over it. A refused request (no user, no people, a bad grade or date) writes nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateBulkGrade
  next: retiredGrade
retiredGrade:
  class: net.officefloor.hq.app.grade.RefuseRetiredBulkGrade
  govern: [ transaction ]
  next: grade
grade:
  class: net.officefloor.hq.app.person.BulkGradePeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithBulkGrade
  govern: [ transaction ]
# Retire a grade on the sheet: people on it keep it, but it cannot be chosen for a new person or in an edit (the form,
# the row's grade, a bulk grade, an import; a quick-add's default grade falls back to A). A refused retire (no user,
# not A, B or C, already retired) writes nothing, not even an audit line.
validate:
  class: net.officefloor.hq.app.grade.ValidateGradeRetire
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.grade.SaveGradeRetire
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.grade.AuditGradeRetired
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.grade.RespondWithGrades
  govern: [ transaction ]
# Edit a person's name and grade. A refused edit (no name, bad grade, unknown person, a name or contact already in use,
# a person saved by someone else since the version the edit was made from) writes nothing, not even an audit line.
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retiredGrade
retiredGrade:
  class: net.officefloor.hq.app.grade.RefuseRetiredPersonGrade
  govern: [ transaction ]
  next: unique
unique:
  class: net.officefloor.hq.app.person.ValidatePersonName
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
